				${name}.m(${update_mount_node}, ${anchor});
			}
		`;

		if (dynamic) {
			block.builders.update.add_block(deindent`
				if (${current_block_type} === (${current_block_type} = ${select_block_type}(changed, ctx)) && ${name}) {
